import{describe,it,expect,beforeEach}from"vitest";import fs from"fs";import path from"path";describe("ISRO Satellite Mission Simulator",()=>{let t,e;beforeEach(()=>{t=fs.readFileSync(path.resolve(__dirname,"../../frontend/satellite-mission/script.js"),"utf-8"),e=fs.readFileSync(path.resolve(__dirname,"../../frontend/satellite-mission/index.html"),"utf-8")}),it("contains famous ISRO mission datasets including Chandrayaan, Mangalyaan, Aditya-L1, Gaganyaan",()=>{expect(t).toContain("MISSIONS_DATA"),expect(t).toContain("Chandrayaan-3"),expect(t).toContain("Mangalyaan (Mars Orbiter Mission)"),expect(t).toContain("Aditya-L1"),expect(t).toContain("Gaganyaan (Crewed Spaceflight)")}),it("contains ISRO launch vehicles for rocket selection challenge",()=>{expect(t).toContain("ROCKETS_DATA"),expect(t).toContain("PSLV-XL"),expect(t).toContain("LVM3-M4"),expect(t).toContain("PSLV-C57"),expect(t).toContain("LVM3-Gaganyaan")}),it("includes mission sequence, difficulty levels, and educational facts UI",()=>{expect(e).toContain('id="mission-select"'),expect(e).toContain('id="difficulty-select"'),expect(e).toContain('id="rocket-options-grid"'),expect(e).toContain('id="educational-facts-box"')})});